function parseAgentJson(raw) {
  if (typeof raw !== 'string') return raw;
  let t = raw.trim();
  const fence = t.match(/^```(?:json)?\s*([\s\S]*?)\s*```$/i);
  if (fence) t = fence[1];
  if (!/^[\{\[]/.test(t.trim())) {
    const m = t.match(/\{[\s\S]*\}/);
    if (m) t = m[0];
  }
  return JSON.parse(t);
}

let data;
try {
  data = parseAgentJson($json.output);
} catch (e) {
  throw new Error('Pick Daily Topics Agent khong tra ve JSON hop le: ' + String($json.output).slice(0, 300));
}

if (!data.topics || !Array.isArray(data.topics) || data.topics.length === 0) {
  throw new Error('Pick Daily Topics Agent thieu field topics[]');
}

const cfg = $('Load Config').first().json;
const topics = data.topics.slice(0, cfg.VIDEOS_PER_DAY);
return topics.map(t => ({
  json: {
    ...cfg,
    niche: t.niche === 'tam_ly' ? 'tam_ly' : 'dau_tu',
    headline: t.headline,
    angle: t.angle || '',
    sourceUrl: t.source_url || ''
  }
}));

const item = $input.item.json;
const now = new Date();
const dateStr = now.toISOString().slice(0, 10).replace(/-/g, '');
const slug = (item.headline || 'video')
  .toLowerCase()
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .replace(/đ/g, 'd').replace(/Đ/g, 'd')
  .replace(/[^a-z0-9]+/g, '-')
  .replace(/(^-|-$)/g, '')
  .slice(0, 40);
const rand = Math.random().toString(36).slice(2, 7);

return {
  json: {
    ...item,
    videoId: `${dateStr}-${slug}-${rand}`,
    channelName: item.channelName || 'Tui dau tu',
    sourceUrl: item.sourceUrl || ''
  }
};

const path = require('path');
const fs = require('fs');

const BASE_DIR = $json.BASE_DIR;

const videoId = $json.videoId;
const videoDir = path.join(BASE_DIR, videoId);
fs.mkdirSync(videoDir, { recursive: true });

return [{
  json: {
    ...$json,
    videoDir,
    storyboardPath: path.join(videoDir, 'storyboard.json'),
    renderScriptPath: path.join(videoDir, 'render_video.sh'),
    thumbnailPath: path.join(videoDir, 'thumbnail_bg.jpg'),
    subscribeClip: path.join(BASE_DIR, 'assets', 'subscribe-tui-dau-tu_final.mp4')
  }
}];

const staticData = $getWorkflowStaticData('global');
staticData.scenes = [];
return $input.all();

