return $input.all().flatMap(item => {
  let raw = item.json.output;
  if (typeof raw === 'string') {
    raw = raw.trim();
    const fenceMatch = raw.match(/^```(?:json)?\s*([\s\S]*?)\s*```$/i);
    if (fenceMatch) raw = fenceMatch[1];
    if (!/^[\{\[]/.test(raw.trim())) {
      const jsonMatch = raw.match(/\{[\s\S]*\}/);
      if (jsonMatch) raw = jsonMatch[0];
    }
  }

  let data;
  try {
    data = JSON.parse(raw);
  } catch (e) {
    const preview = String(item.json.output || '').slice(0, 300);
    throw new Error(`Screen Planner KHONG tra JSON hop le.\n--- 300 ky tu dau ---\n${preview}`);
  }

  if (!data.scenes || !Array.isArray(data.scenes)) {
    throw new Error('Screen Planner tra JSON nhung thieu field "scenes" dang mang.');
  }

  const cleanScenes = data.scenes.filter(scene => {
    const text = (scene.narration || '').trim();
    return text.length > 0 && !/^\(.*\)$/.test(text);
  });

  const total = cleanScenes.reduce((s, sc) => s + (Number(sc.duration) || 0), 0);
  // FIX (workflow bi stuck/that bai toan bo pipeline chi vi uoc luong lech vai
  // giay): field 'duration' o day chi la UOC LUONG cua Screen Planner - thoi
  // luong THAT cua video duoc quyet dinh boi audio TTS that (ffprobe do truc
  // tiep trong Build Render Script), KHONG phai field nay (xem duration: scene.
  // duration ben duoi chi de luu vao storyboard.json, khong dung de dung clip).
  // Vi vay KHONG throw Error lam dung ca pipeline (mat het cong Research Agent +
  // Screen Planner da chay) chi vi model local uoc luong lech nhe so voi muc
  // tieu 90-120s - chi canh bao va van tiep tuc chay binh thuong. Chi throw that
  // su neu tong qua bat thuong (gan nhu chac chan la output loi/thieu scene).
  if (total < 20 || total > 200) {
    throw new Error('Tong duration UOC LUONG cua scenes = ' + total.toFixed(1) + 's, qua bat thuong (ngoai 20-200s) - Screen Planner co the da tra ve output loi/thieu scene.');
  }
  if (total < 90 || total > 120) {
    console.log('[CANH BAO] Tong duration UOC LUONG cua scenes = ' + total.toFixed(1) + 's, ngoai muc tieu 90-120s. Van tiep tuc vi thoi luong THAT cua video phu thuoc audio TTS thuc te, khong phai field uoc luong nay.');
  }

  return cleanScenes.map(scene => ({
    json: {
      video_style: data.video_style,
      theme: data.theme,
      aspect_ratio: data.aspect_ratio,
      fps: data.fps,
      ...scene
    }
  }));
});

return $input.all().map((item, index) => ({
  json: { ...item.json, sceneId: index + 1 },
  binary: { audio: item.binary.data }
}));

const scene = $input.item.json;
const videoDir = $('Init Paths').first().json.videoDir;
const sceneId = scene.sceneId;

const audioPath = `${videoDir}/scene_${sceneId}_audio.wav`;
const videoPath = `${videoDir}/scene_${sceneId}_video.mp4`;

const stockQuery = (scene.asset && scene.asset.stock_query) || ($('Generate Video ID').first().json.niche === 'tam_ly' ? 'calm lifestyle emotion background' : 'financial news background');

return {
  json: { ...scene, audioPath, videoPath, stockQuery },
  binary: $input.item.binary
};

const scene = $('Build Video Queries').first().json;
const videos = $json.videos || [];

// Uu tien video huong DOC (height > width) - Pexels orientation=portrait doi
// khi van tra ve vai video ngang, bo qua neu con lua chon khac.
const portraitVideos = videos.filter(v => (v.height || 0) > (v.width || 0));
const pool = portraitVideos.length ? portraitVideos : videos;
const video = pool[0];

if (!video) {
  throw new Error('Pexels khong tra ve video nao cho query: ' + (scene.stockQuery || ''));
}

const files = (video.video_files || []).slice().sort((a, b) => (b.width * b.height) - (a.width * a.height));
const portraitFiles = files.filter(f => (f.height || 0) > (f.width || 0));
const filePool = portraitFiles.length ? portraitFiles : files;
// Uu tien file do phan giai vua phai (<=1080p ngang) de tai nhanh, khong can 4K.
const chosen = filePool.find(f => (f.width || 0) <= 1080 && (f.width || 0) > 0) || filePool[0];
const videoUrl = chosen && chosen.link;

if (!videoUrl) {
  throw new Error('Pexels tra ve video nhung khong co video_files hop le cho query: ' + (scene.stockQuery || ''));
}

return { json: { ...scene, pexelsVideoUrl: videoUrl } };

const scene = $('Extract Pexels Video URL').first().json;

const staticData = $getWorkflowStaticData('global');
if (!staticData.scenes) staticData.scenes = [];
staticData.scenes.push({
  sceneId: scene.sceneId,
  scene_type: scene.scene_type,
  headline: scene.headline,
  narration: scene.narration,
  duration: scene.duration,
  animation: scene.animation,
  transition: scene.transition,
  subtitle_style: scene.subtitle_style,
  highlight_words: scene.highlight_words,
  importance: scene.importance,
  audioPath: scene.audioPath,
  videoPath: scene.videoPath
});

return {
  json: scene,
  binary: { video: $input.item.binary.data }
};

const staticData = $getWorkflowStaticData('global');
const videoId = $('Generate Video ID').first().json.videoId;

const storyboard = {
  channel: $('Generate Video ID').first().json.channelName,
  videoId,
  aspect_ratio: '9:16',
  fps: 30,
  scenes: (staticData.scenes || []).sort((a, b) => a.sceneId - b.sceneId)
};

const jsonStr = JSON.stringify(storyboard, null, 2);
const buffer = Buffer.from(jsonStr, 'utf-8');

return [{
  json: { videoId, storyboardPath: $('Init Paths').first().json.storyboardPath },
  binary: { storyboard: await this.helpers.prepareBinaryData(buffer, 'storyboard.json', 'application/json') }
}];

const { execSync } = require('child_process');
const W = 1080, H = 1920;
const WORDS_PER_CHUNK = 4; // so tu toi da hien thi cung luc tren man hinh
const staticData = $getWorkflowStaticData('global');
const scenes = (staticData.scenes || []).slice().sort((a, b) => a.sceneId - b.sceneId);
const dir = $('Init Paths').first().json.videoDir;

const YELLOW = '&H00FFFF&'; // ASS la BGR: vang = B00 G FF R FF
const WHITE = '&HFFFFFF&';

const assHeader = [
  '[Script Info]',
  'ScriptType: v4.00+',
  `PlayResX: ${W}`,
  `PlayResY: ${H}`,
  'WrapStyle: 0',
  'ScaledBorderAndShadow: yes',
  '',
  '[V4+ Styles]',
  'Format: Name, Fontname, Fontsize, PrimaryColour, SecondaryColour, OutlineColour, BackColour, Bold, Italic, Underline, StrikeOut, ScaleX, ScaleY, Spacing, Angle, BorderStyle, Outline, Shadow, Alignment, MarginL, MarginR, MarginV, Encoding',
  'Style: Default,Arial,68,&H00FFFFFF,&H000000FF,&H00000000,&H00000000,-1,0,0,0,100,100,0,0,1,4,1,2,60,60,160,1',
  '',
  '[Events]',
  'Format: Layer, Start, End, Style, Name, MarginL, MarginR, MarginV, Effect, Text'
].join('\n');

function esc(text) {
  // { } co the bi hieu nham la override tag trong ASS.
  return String(text || '').replace(/\{/g, '(').replace(/\}/g, ')');
}

function fmtTime(sec) {
  const h = Math.floor(sec / 3600);
  const m = Math.floor((sec % 3600) / 60);
  const s = (sec - h * 3600 - m * 60).toFixed(2);
  return `${h}:${String(m).padStart(2, '0')}:${s.padStart(5, '0')}`;
}

const dialogueLines = [];
let subOffset = 0;

for (const scene of scenes) {
  const audioPath = scene.audioPath;
  const audioDur = parseFloat(execSync(
    `ffprobe -v error -show_entries format=duration -of default=noprint_wrappers=1:nokey=1 "${audioPath}"`
  ).toString().trim()) || 0;
  const dur = audioDur + 0.6; // padding, phai khop CHINH XAC voi Build Render Script

  const words = String(scene.narration || '').trim().split(/\s+/).filter(Boolean);
  if (words.length === 0) { subOffset += dur; continue; }

  const totalChars = words.reduce((s, w) => s + w.length, 0) || 1;
  const chunks = [];
  for (let i = 0; i < words.length; i += WORDS_PER_CHUNK) chunks.push(words.slice(i, i + WORDS_PER_CHUNK));

  let sceneElapsed = 0;
  for (const chunk of chunks) {
    const chunkChars = chunk.reduce((s, w) => s + w.length, 0) || 1;
    const chunkDur = dur * (chunkChars / totalChars);
    const chunkStart = sceneElapsed;

    let wordElapsed = 0;
    for (let wi = 0; wi < chunk.length; wi++) {
      const wordDur = chunkDur * (chunk[wi].length / chunkChars);
      const start = subOffset + chunkStart + wordElapsed;
      const end = start + wordDur;
      const text = chunk.map((w, i) => i === wi ? `{\\c${YELLOW}}${esc(w)}{\\c${WHITE}}` : esc(w)).join(' ');
      dialogueLines.push(`Dialogue: 0,${fmtTime(start)},${fmtTime(end)},Default,,0,0,0,,${text}`);
      wordElapsed += wordDur;
    }
    sceneElapsed += chunkDur;
  }

  subOffset += dur;
}

const assContent = assHeader + '\n' + dialogueLines.join('\n') + '\n';
const buffer = Buffer.from(assContent, 'utf-8');

return [{
  json: { subtitlesPath: `${dir}/subtitles.ass` },
  binary: { subtitles: await this.helpers.prepareBinaryData(buffer, 'subtitles.ass', 'text/plain') }
}];

// !!! DOI duong dan SUBSCRIBE_CLIP cho dung may ban neu can !!!
// !!! DOI SCENE_TIMEOUT_SEC neu may ban render cham/nhanh hon muc mac dinh !!!
// Dinh dang SHORTS doc 9:16 (1080x1920)
const W = 1080, H = 1920, FPS = 30;
const SCENE_TIMEOUT_SEC = 300;
const PRESET = 'veryfast';
const staticData = $getWorkflowStaticData('global');
const scenes = (staticData.scenes || []).slice().sort((a, b) => a.sceneId - b.sceneId);
const videoId = $('Generate Video ID').first().json.videoId;
const dir = $('Init Paths').first().json.videoDir;
const subscribeClip = $('Init Paths').first().json.subscribeClip;

// FIX (2026-07-28): khong con dung anh tinh + zoompan Ken Burns nua - moi
// scene gio la 1 CLIP VIDEO NGAN tai tu Pexels (xem Build Video Queries/
// Pexels Video Search). subtitles.ass da duoc node 'Build Subtitles (ASS)'
// ghi san (caption ngan, karaoke tu-vang) TRUOC buoc nay - o day chi can
// tham chieu toi file do, khong tu sinh ASS header/dialogue nua.
let script = `#!/bin/bash
set -e
# ffmpeg chuan cua Homebrew KHONG co libass/freetype (thieu filter 'ass').
# Uu tien dung ffmpeg-full (co libass) neu da cai, fallback ve ffmpeg mac dinh.
if [ -d "/opt/homebrew/opt/ffmpeg-full/bin" ]; then
  export PATH="/opt/homebrew/opt/ffmpeg-full/bin:$PATH"
fi
cd "${dir}"

exec 2>> "${dir}/ffmpeg_error.log"

PROGRESS_LOG="${dir}/render_progress.log"
> "$PROGRESS_LOG"

SUBSCRIBE_SRC="${subscribeClip}"
SUBSCRIBE_NORMALIZED="${dir}/subscribe_normalized.mp4"
if [ ! -f "$SUBSCRIBE_NORMALIZED" ]; then
  echo "[$(date '+%H:%M:%S')] Chuan hoa clip subscribe cho khop ${W}x${H}@${FPS}fps" | tee -a "$PROGRESS_LOG"
  ffmpeg -y -hide_banner -loglevel error -i "$SUBSCRIBE_SRC" -vf "scale=${W}:${H}:force_original_aspect_ratio=decrease,pad=${W}:${H}:(ow-iw)/2:(oh-ih)/2:color=black,setsar=1,fps=${FPS}" -c:v libx264 -preset ${PRESET} -crf 18 -pix_fmt yuv420p -af "volume=0.8" -c:a aac -b:a 192k -ar 44100 -ac 2 "$SUBSCRIBE_NORMALIZED"
fi
`;

let idx = 0;
const processed = [];
for (const scene of scenes) {
  idx++;
  const id = scene.sceneId;
  const clip = `scene_${id}_video.mp4`;
  const audio = `scene_${id}_audio.wav`;
  const out = `scene_${id}_clip.mp4`;
  processed.push(out);

  script += `
echo "[$(date '+%H:%M:%S')] BAT DAU scene ${idx}/${scenes.length} (id=${id})" | tee -a "$PROGRESS_LOG"

AUDIO_DUR=$(ffprobe -v error -show_entries format=duration -of default=noprint_wrappers=1:nokey=1 "${audio}")
DUR=$(awk -v d="$AUDIO_DUR" 'BEGIN{printf "%.2f", d+0.6}')

if ! timeout ${SCENE_TIMEOUT_SEC}s ffmpeg -y -hide_banner -loglevel error -stream_loop -1 -i "${clip}" -i "${audio}" -filter_complex "[0:v]scale=${W}:${H}:force_original_aspect_ratio=increase,crop=${W}:${H},setsar=1[v]" -map "[v]" -map 1:a -c:v libx264 -preset ${PRESET} -crf 18 -pix_fmt yuv420p -r ${FPS} -c:a aac -b:a 192k -ar 44100 -ac 2 -t "$DUR" "${out}"; then
  echo "[$(date '+%H:%M:%S')] !!! Scene ${id} loi hoac vuot qua ${SCENE_TIMEOUT_SEC}s" | tee -a "$PROGRESS_LOG"
  exit 1
fi

echo "[$(date '+%H:%M:%S')] XONG scene ${idx}/${scenes.length}" | tee -a "$PROGRESS_LOG"
`;
}

