  const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
  const isJpeg = buffer.length > 4 && buffer[0] === 0xFF && buffer[1] === 0xD8;
  const isPng = buffer.length > 8 && buffer[0] === 0x89 && buffer[1] === 0x50;
  const isWebp = buffer.length > 12 && buffer.slice(8, 12).toString() === 'WEBP';
  const dims = getImageDimensions(buffer);
  const meetsResolution = isWebp ? true : (dims ? Math.min(dims.width, dims.height) >= MIN_DIMENSION : false);
  isValid = buffer.length > 2000 && (isJpeg || isPng || isWebp) && meetsResolution;
}

return { json: { ...scene, tavilyImageValid: isValid }, binary: $input.item.binary };

